유해·위험문구: H314 : 피부에 심한 화상과 눈에 손상을 일으킴|H317 : 알레르기성 피부 반응을 일으킬 수 있음|H318 : 눈에 심한 손상을 일으킴|H334 : 흡입시 알레르기성 반응,천식 또는 호흡 곤란 등을 일으킬 수 있음|H335 : 호흡기 자극을 일으킬 수 있음|H373 : 장기간 또는 반복노출 되면 장기(영향을 받는 것으로 알려진 모든 장기를 명시한다.)에 손상을 일으킬 수 있음(특정표적장기독성(반복노출)을 일으키는 노출 경로를 기재. 단, 다른 노출경로에 의해 특정표적장기독성(반복노출)을 일으키지 않는다는 결정적인 증거가 있는 경우에 한한다.)
예방: P260 : 분진/흄/가스/미스트/증기/스프레이를(을)흡입하지 마시오.|P261 : 분진/흄/가스/미스트/증기/스프레이의 흡입을 피하시오.|P264 : 취급 후에는…을(를)철저히 씻으시오.|P271 : 옥외 또는 환기가 잘 되는 곳에서만 취급하시오.|P272 : 작업장 밖으로 오염된 의류를 반출하지 마시오.|P280 : 보호장갑/보호의/보안경/안면보호구를(을)착용하시오.|P284 : [환기가 잘 되지 않는 경우]호흡기 보호구를 착용하시오.
대응: P301+P330+P331 : 삼켰다면:입을 씻어내시오.토하게 하지 마시오.|P302+P352 : 피부에 묻으면:다량의 물/…(으)로 씻으시오.|P303+P361+P353 : 피부(또는 머리카락)에 묻으면:오염된 모든 의류를 즉시 벗으시오.피부를 물로 씻으시오[또는 샤워하시오].|P304+P340 : 흡입하면:신선한 공기가 있는 곳으로 옮기고 호흡하기 쉬운 자세로 안정을 취하시오.|P305+P351+P338 : 눈에 묻으면:몇 분간 물로 조심해서 씻으시오.가능하면 콘택트렌즈를 제거하시오.계속 씻으시오.|P310 : 즉시 의료기관/의사/…의 진찰을 받으시오.|P312 : 불편함을 느끼면 의료기관/의사/…의 진찰을 받으시오.|P314 : 불편함을 느끼면 의학적인 조치/조언을 받으시오.|P321 : …처치를 하시오.|P333+P313 : 피부 자극 또는 홍반이 나타나면:의학적인 조치/조언을 받으시오.|P342+P311 : 호흡기 증상이 나타나면:의료기관/의사/…의 진찰을 받으시오.|P362+P364 : 오염된 의류를 벗고 다시 사용 전 세척하시오.|P363 : 다시 사용 전 오염된 의류를 세척하시오.
저장: P403+P233 : 환기가 잘 되는 곳에 보관하시오.용기를 단단히 밀폐하시오.|P405 : 잠금장치를 하여 저장하시오.
