피부에 접촉했을 때: 뜨거운 물질인 경우, 열을 없애기 위해 영향을 받은 부위를 다량의 차가운 물에 담그거나 씻어내시오|긴급 의료조치를 받으시오|오염된 옷과 신발을 제거하고 오염지역을 격리하시오|물질과 접촉시 즉시 20분 이상 흐르는 물에 피부와 눈을 씻어내시오|경미한 피부 접촉 시 오염부위 확산을 방지하시오|피부자극성 또는 홍반이 나타나면 의학적인 조치·조언을 구하시오.|오염된 의복은 벗고 다시 사용 전 세탁하시오.
흡입했을 때: 과량의 먼지 또는 흄에 노출된 경우 깨끗한 공기로 제거하고 기침이나 다른 증상이 있을 경우 의료 조치를 취하시오.|호흡하지 않는 경우 인공호흡을 실시하시오|호흡이 힘들 경우 산소를 공급하시오|즉시 의료기관(의사)의 진찰을 받으시오.
